fn fit_plane(x1: &[f32], x2: &[f32], z: &[f32]) -> Result<nalgebra::Matrix<f32, nalgebra::Const<3>, nalgebra::Const<1>, nalgebra::ArrayStorage<f32, 3, 1>>> {
    use nalgebra::{OMatrix, Dyn, U3};
    
    type DesignMatrix = OMatrix<f32, Dyn, U3>;

    let n = x1.len();
    let mut x_data = Vec::with_capacity(n * 3);
    for i in 0..n {
        x_data.push(1.0);
        x_data.push(x1[i]);
        x_data.push(x2[i]);
    }
    let x = DesignMatrix::from_row_slice(&x_data);       // Dyn × U3, n inferred from x_data.len()/3
    let z = nalgebra::DVector::from_row_slice(z);         // still Dyn — length n

    let xt = x.transpose();       // U3 × Dyn
    let xtx = &xt * &x;           // U3 × U3

    match xtx.try_inverse() {
        Some(v) => Ok(v* &xt * z),
        None => Err(Error {
            issue: "Insufficient or inconsistent data in measurements.".to_string(),
            fault: ErrorFault::User,
            solution: "Double check and modify data, or revert to defaults."
        }),
    }  // U3 — statically length-3
}

