pub struct FixedHookCalculator {
    height_coeffs: (f32, f32),
    width_coeffs: (f32, f32),
}

impl FixedHookCalculator {
    pub fn from_sizes_calculator(calculator: SizesCalculator, hook_size_mm: f32) -> Result<Self> {
        let result = Self {
            height_coeffs: (calculator.height_coeffs.0 + calculator.height_coeffs.2 * hook_size_mm, calculator.height_coeffs.1),
            width_coeffs: (calculator.width_coeffs.0 + calculator.width_coeffs.2 * hook_size_mm, calculator.width_coeffs.1),
        };
        
        let tests = [
            result.to_stl_units(1.0, true),
            result.to_stl_units(3.0, true),
            result.to_stl_units(1.0, false),
            result.to_stl_units(3.0, false),
        ];
        assert(
            tests.iter().all(|v| *v > 0.0),
            "Measurement values are predicting negative or zero lengths.",
            "Correct measurement values or revert to defaults.",
            ErrorFault::User
        )?;

        Ok(result)
    }

    pub fn to_stl_units(&self, relative_size: f32, height: bool) -> f32 {
        if height {
            self.height_coeffs.0 + self.height_coeffs.1 * relative_size
        } else {
            self.width_coeffs.0 + self.width_coeffs.1 * relative_size
        }
    }

    pub fn from_stl_units(&self, stl_units: f32, height: bool) -> f32 {
        if height {
            (stl_units - self.height_coeffs.0) / self.height_coeffs.1
        } else {
            (stl_units - self.width_coeffs.0) / self.width_coeffs.1
        }
    }
}

